#!/usr/bin/env node

/**
 * Moonlighter Fandom item downloader.
 *
 * Generated by Codex - ChatGPT 5.6 Terra
 *
 * This script queries the wiki's Cargo data for every culture, derives each
 * item's base value from its PerfectN field, calculates the selling prices used
 * by the wiki templates, and downloads the associated image. Run with:
 *
 *     node moonlighter.js
 */

const fs = require("node:fs/promises");
const path = require("node:path");
const http = require("node:http");
const https = require("node:https");

// The Fandom API endpoint used for Cargo, page parsing, and file resolution.
const API_URL = "https://moonlighter.fandom.com/api.php";

const USER_AGENT =
	"MoonlighterFetcher/0.1.1 (https://github.com/r58iiz/moonlighter-overlay) Node.js/24";

// Network defaults.  Each request is retried for transient failures, follows
// redirects, and is forcefully timed out so one stalled connection cannot stop
// the complete import.
const REQUEST_TIMEOUT_MS = 30_000;
const MAX_RETRIES = 3;
const MAX_REDIRECTS = 8;

// MediaWiki applies strict anonymous API limits. Pace API calls and retry the
// explicit "ratelimited" response so a large all-culture import can continue.
const API_MIN_INTERVAL_MS = 6_000;
const MAX_API_RATE_LIMIT_RETRIES = 5;
const API_RATE_LIMIT_RETRY_MS = 30_000;
let nextApiRequestAt = 0;

// The requested output order is explicit: do not rely on object property order
// or the wiki's own order for cultures.
const CULTURES = [
	{ name: "Merchant", directory: "merchant" },
	{ name: "Golem", directory: "golem" },
	{ name: "Forest", directory: "forest" },
	{ name: "Desert", directory: "desert" },
	{ name: "Tech", directory: "tech" },
	{ name: "Interdimensional", directory: "interdimensional" },
	{ name: "ICT", directory: "ict" },
];

/**
 * Sleep between retries.  Keeping this helper separate makes retry timing
 * clear and avoids duplicated Promise boilerplate in the HTTP helper.
 *
 * @param {number} milliseconds Number of milliseconds to wait.
 * @returns {Promise<void>}
 */
function sleep(milliseconds) {
	return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

/**
 * Return a request URL with the supplied MediaWiki API parameters appended.
 * URLSearchParams performs all necessary escaping, including item titles and
 * Cargo's quoted culture expression.
 *
 * @param {Record<string, string | number>} parameters API parameters.
 * @returns {string} Fully encoded API URL.
 */
function buildApiUrl(parameters) {
	const url = new URL(API_URL);

	for (const [key, value] of Object.entries(parameters)) {
		url.searchParams.set(key, String(value));
	}

	return url.toString();
}

/**
 * Determine whether a status code is a redirect which may carry a Location
 * header.  HTTP method is always GET, so all standard redirect responses may
 * safely be followed here.
 *
 * @param {number} statusCode HTTP status code.
 * @returns {boolean} True for redirect status codes.
 */
function isRedirect(statusCode) {
	return [301, 302, 303, 307, 308].includes(statusCode);
}

/**
 * Make one HTTP(S) GET request and return its complete response body.
 *
 * The helper supports both JSON API calls and binary image downloads because
 * it returns a Buffer.  It follows redirects, reports useful failure details,
 * and destroys requests that exceed the configured deadline.
 *
 * @param {string} requestUrl URL to retrieve.
 * @param {number} redirectCount Number of redirects already followed.
 * @returns {Promise<{body: Buffer, headers: http.IncomingHttpHeaders, url: string}>}
 */
function requestOnce(requestUrl, redirectCount = 0) {
	return new Promise((resolve, reject) => {
		let parsedUrl;

		try {
			parsedUrl = new URL(requestUrl);
		} catch (error) {
			reject(new Error(`Invalid URL "${requestUrl}": ${error.message}`));
			return;
		}

		const transport =
			parsedUrl.protocol === "https:"
				? https
				: parsedUrl.protocol === "http:"
					? http
					: null;
		if (!transport) {
			reject(
				new Error(
					`Unsupported URL protocol "${parsedUrl.protocol}" for ${requestUrl}`,
				),
			);
			return;
		}

		const request = transport.get(
			parsedUrl,
			{
				headers: {
					"User-Agent": USER_AGENT,
					Accept: "application/json, text/plain, */*",
				},
			},
			(response) => {
				const statusCode = response.statusCode || 0;

				if (isRedirect(statusCode)) {
					const location = response.headers.location;
					response.resume(); // Discard this body before following its redirect.

					if (!location) {
						reject(
							new Error(
								`Redirect (${statusCode}) from ${requestUrl} did not include a Location header`,
							),
						);
						return;
					}

					if (redirectCount >= MAX_REDIRECTS) {
						reject(
							new Error(`Too many redirects while requesting ${requestUrl}`),
						);
						return;
					}

					let nextUrl;
					try {
						nextUrl = new URL(location, parsedUrl).toString();
					} catch (error) {
						reject(
							new Error(
								`Invalid redirect URL from ${requestUrl}: ${error.message}`,
							),
						);
						return;
					}

					resolve(requestOnce(nextUrl, redirectCount + 1));
					return;
				}

				const chunks = [];
				response.on("data", (chunk) => chunks.push(chunk));
				response.on("error", (error) =>
					reject(
						new Error(`Response error from ${requestUrl}: ${error.message}`),
					),
				);
				response.on("end", () => {
					const body = Buffer.concat(chunks);

					if (statusCode < 200 || statusCode >= 300) {
						const preview = body
							.toString("utf8", 0, 300)
							.replace(/\s+/g, " ")
							.trim();
						reject(
							new Error(
								`HTTP ${statusCode} from ${requestUrl}${preview ? `: ${preview}` : ""}`,
							),
						);
						return;
					}

					resolve({ body, headers: response.headers, url: requestUrl });
				});
			},
		);

		request.setTimeout(REQUEST_TIMEOUT_MS, () => {
			request.destroy(
				new Error(`Request timed out after ${REQUEST_TIMEOUT_MS} ms`),
			);
		});

		request.on("error", (error) =>
			reject(new Error(`Request failed for ${requestUrl}: ${error.message}`)),
		);
	});
}

/**
 * Fetch an HTTP(S) resource with retry support.  Retry delays grow modestly
 * to avoid immediately repeating a request during temporary wiki throttling.
 *
 * @param {string} requestUrl URL to retrieve.
 * @returns {Promise<{body: Buffer, headers: http.IncomingHttpHeaders, url: string}>}
 */
async function fetchResource(requestUrl) {
	let lastError;

	for (let attempt = 1; attempt <= MAX_RETRIES; attempt += 1) {
		try {
			return await requestOnce(requestUrl);
		} catch (error) {
			lastError = error;

			if (attempt < MAX_RETRIES) {
				await sleep(attempt * 1_000);
			}
		}
	}

	throw new Error(`Failed after ${MAX_RETRIES} attempts: ${lastError.message}`);
}

/**
 * Retrieve and parse a JSON response through the common HTTP helper.
 *
 * @param {string} requestUrl URL expected to return JSON.
 * @returns {Promise<Record<string, unknown>>} Parsed JSON object.
 */
async function fetchJson(requestUrl) {
	const { body, url } = await fetchResource(requestUrl);
	const text = body.toString("utf8");

	try {
		return JSON.parse(text);
	} catch (error) {
		const preview = text.slice(0, 300).replace(/\s+/g, " ").trim();
		throw new Error(
			`Invalid JSON returned by ${url}: ${error.message}${preview ? ` (${preview})` : ""}`,
		);
	}
}

/**
 * Fetch one MediaWiki API response at a deliberately polite rate. HTTP retries
 * are handled by fetchResource; this helper additionally retries MediaWiki's
 * successful-but-ratelimited JSON response after a progressively longer wait.
 *
 * @param {Record<string, string | number>} parameters API parameters.
 * @param {string} operation Human-readable operation name.
 * @returns {Promise<Record<string, unknown>>} Parsed API response.
 */
async function fetchApiJson(parameters, operation) {
	for (let attempt = 1; attempt <= MAX_API_RATE_LIMIT_RETRIES; attempt += 1) {
		const waitTime = nextApiRequestAt - Date.now();
		if (waitTime > 0) {
			await sleep(waitTime);
		}

		nextApiRequestAt = Date.now() + API_MIN_INTERVAL_MS;
		const data = await fetchJson(buildApiUrl(parameters));
		const apiError =
			data.error && typeof data.error === "object" ? data.error : null;
		const errorCode =
			apiError && typeof apiError.code === "string" ? apiError.code : "";

		if (errorCode !== "ratelimited") {
			throwForApiError(data, operation);
			return data;
		}

		if (attempt === MAX_API_RATE_LIMIT_RETRIES) {
			throwForApiError(data, operation);
		}

		const retryDelay = API_RATE_LIMIT_RETRY_MS * attempt;
		console.error(
			`  API rate limited while ${operation}; retrying in ${Math.ceil(retryDelay / 1000)} seconds...`,
		);
		await sleep(retryDelay);
	}

	throw new Error(`${operation} exhausted its API rate-limit retries`);
}
/**
 * Fail clearly when MediaWiki returns an API-level error in an otherwise valid
 * JSON response.
 *
 * @param {Record<string, unknown>} data API response data.
 * @param {string} operation Human-readable operation name.
 */
function throwForApiError(data, operation) {
	if (data.error && typeof data.error === "object") {
		const apiError = data.error;
		const code = typeof apiError.code === "string" ? apiError.code : "unknown";
		const info =
			typeof apiError.info === "string"
				? apiError.info
				: "Unknown MediaWiki error";
		throw new Error(`${operation} failed (${code}): ${info}`);
	}
}

/**
 * Query Cargo once for every item's name and perfect-normal sale price in one
 * culture. PerfectN is enough to reconstruct the original base value exactly,
 * removing the need for one action=parse request per item.
 *
 * @param {string} culture Culture label exactly as stored by Cargo.
 * @returns {Promise<Array<{name: string, perfectN: string | number}>>} Item references.
 */
async function fetchCultureItems(culture) {
	const data = await fetchApiJson(
		{
			action: "cargoquery",
			tables: "Item",
			fields: "Name,PerfectN",
			where: `Culture="${culture}"`,
			limit: 500,
			format: "json",
		},
		`Cargo query for ${culture}`,
	);

	if (!Array.isArray(data.cargoquery)) {
		throw new Error(`Cargo query for ${culture} returned no cargoquery array`);
	}

	const items = [];
	for (const row of data.cargoquery) {
		if (
			!row ||
			typeof row !== "object" ||
			!row.title ||
			typeof row.title !== "object"
		) {
			continue;
		}

		const name = row.title.Name;
		const perfectN = row.title.PerfectN;
		if (typeof name === "string" && name.trim()) {
			items.push({ name: name.trim(), perfectN });
		}
	}

	return items;
}
/**
 * Recover the integer base value from Cargo's PerfectN value. The wiki uses
 * PerfectN = value + ceil(value / 10), equivalently ceil(11 * value / 10).
 * For every non-negative integer value, the exact inverse is
 * floor(PerfectN * 10 / 11). Rechecking the forward formula prevents malformed
 * Cargo data from silently producing incorrect prices.
 *
 * @param {string | number} perfectN Cargo PerfectN field.
 * @returns {bigint} Original base item value.
 */
function getBaseValueFromPerfectN(perfectN) {
	const text = String(perfectN).trim();
	if (!/^\d+$/.test(text)) {
		throw new Error(`Cargo PerfectN is not an integer: ${perfectN}`);
	}

	const normalPrice = BigInt(text);
	const value = (normalPrice * 10n) / 11n;
	if (value + ceilDivide(value, 10n) !== normalPrice) {
		throw new Error(`Cargo PerfectN cannot be inverted exactly: ${perfectN}`);
	}

	return value;
}
/**
 * Integer ceiling division for positive BigInts.  BigInt is used throughout
 * the formulas so every result is exact and follows MediaWiki floor()/ceil()
 * behavior without floating-point rounding edge cases.
 *
 * @param {bigint} numerator Positive integer numerator.
 * @param {bigint} denominator Positive integer denominator.
 * @returns {bigint} ceil(numerator / denominator).
 */
function ceilDivide(numerator, denominator) {
	return (numerator + denominator - 1n) / denominator;
}

/**
 * Return the larger of two BigInts. Math.max cannot accept BigInts, so this
 * helper keeps the NG+ floor-at-zero calculations exact.
 *
 * @param {bigint} left First integer.
 * @param {bigint} right Second integer.
 * @returns {bigint} The greater integer.
 */
function maxBigInt(left, right) {
	return left > right ? left : right;
}

/**
 * Convert a BigInt price into a JSON number, refusing unsafe values rather
 * than silently corrupting output.  Moonlighter values are well below this
 * limit, but the check makes malformed remote data visible.
 *
 * @param {bigint} value Integer value to serialize.
 * @param {string} context Description for an error message.
 * @returns {number} Safe JavaScript integer.
 */
function toSafeNumber(value, context) {
	if (value > BigInt(Number.MAX_SAFE_INTEGER)) {
		throw new Error(`${context} exceeds JavaScript's safe integer range`);
	}

	return Number(value);
}

/**
 * Calculate template-perfect selling prices from the supplied base value.
 * Formula source:
 *   https://moonlighter.fandom.com/wiki/Template:Sales_Table_Auto?action=raw
 *   https://moonlighter.fandom.com/wiki/Template:Item_Page?action=raw
 * Base game:
 *   perfectL = floor(value * .75) + ceil(floor(value * .75) * .10)
 *   perfectN = value + ceil(value * .10)
 *   perfectH = value + ceil(value * .35)
 *
 * NG+ first uses ngValue = ceil(value * 5.6), then applies the same formula
 * components with the template's final -1.  Fractions are represented as
 * integers (3/4, 1/10, 7/20, and 28/5), never floating point.
 *
 * @param {bigint} value Base item value.
 * @returns {{prices: {low: number, normal: number, high: number}, ng_plus_prices: {low: number, normal: number, high: number}}}
 */
function calculatePrices(value) {
	const baseLow = (value * 3n) / 4n;
	const low = baseLow + ceilDivide(baseLow, 10n);
	const normal = value + ceilDivide(value, 10n);
	const high = value + ceilDivide(value * 7n, 20n);

	const ngValue = ceilDivide(value * 28n, 5n);
	const ngBaseLow = (ngValue * 3n) / 4n;

	// Template formulas subtract one from NG+ prices. Clamp each result to zero
	// so zero-value items never emit a negative selling price.
	const ngLow = maxBigInt(ngBaseLow + ceilDivide(ngBaseLow, 10n) - 1n, 0n);
	const ngNormal = maxBigInt(ngValue + ceilDivide(ngValue, 10n) - 1n, 0n);
	const ngHigh = maxBigInt(ngValue + ceilDivide(ngValue * 7n, 20n) - 1n, 0n);

	return {
		prices: {
			low: toSafeNumber(low, "Base low price"),
			normal: toSafeNumber(normal, "Base normal price"),
			high: toSafeNumber(high, "Base high price"),
		},
		ng_plus_prices: {
			low: toSafeNumber(ngLow, "NG+ low price"),
			normal: toSafeNumber(ngNormal, "NG+ normal price"),
			high: toSafeNumber(ngHigh, "NG+ high price"),
		},
	};
}

/**
 * Keep every API image lookup within MediaWiki's standard titles limit. Batch
 * resolution is the key to avoiding hundreds of separate action=query calls.
 */
const IMAGE_TITLES_PER_QUERY = 50;

/**
 * Normalize a MediaWiki file title so Cargo-generated names and API response
 * titles compare reliably: MediaWiki typically converts underscores to spaces.
 *
 * @param {string} title File title with or without File:.
 * @returns {string} Comparable filename.
 */
function normalizeFileTitle(title) {
	return title.replace(/^(?:File|Image):/i, "").replace(/ /g, "_");
}

/**
 * Resolve up to 50 image filenames in one action=query request. Every image
 * still comes from MediaWiki's returned imageinfo URL; no CDN path is guessed.
 *
 * @param {string[]} imageNames Filenames without File:.
 * @returns {Promise<Map<string, string>>} Filename-to-resolved-URL map.
 */
async function resolveImageUrlsBatch(imageNames) {
	if (imageNames.length === 0) {
		return new Map();
	}

	const data = await fetchApiJson(
		{
			action: "query",
			titles: imageNames.map((imageName) => `File:${imageName}`).join("|"),
			prop: "imageinfo",
			iiprop: "url",
			format: "json",
		},
		`Image resolution batch (${imageNames.length} files)`,
	);

	const pages =
		data.query && typeof data.query === "object" ? data.query.pages : undefined;
	if (!pages || typeof pages !== "object") {
		throw new Error("Image resolution batch did not return pages");
	}

	const resolvedUrls = new Map();
	for (const page of Object.values(pages)) {
		if (
			!page ||
			typeof page !== "object" ||
			typeof page.title !== "string" ||
			!Array.isArray(page.imageinfo)
		) {
			continue;
		}

		const url = page.imageinfo[0]?.url;
		if (typeof url === "string" && url) {
			resolvedUrls.set(normalizeFileTitle(page.title), url);
		}
	}

	return resolvedUrls;
}

/**
 * Resolve generated image names for a complete culture in batches. PNG is tried
 * first, then alternate formats only for items still unresolved, minimizing the
 * number of API requests while retaining a practical fallback for odd files.
 *
 * @param {Array<{name: string}>} items Culture items.
 * @returns {Promise<Map<string, string>>} Item-name-to-resolved-URL map.
 */
async function resolveGeneratedImageUrls(items) {
	const itemUrls = new Map();
	let unresolvedNames = items.map((item) => item.name);
	const extensions = [".png", ".webp", ".jpg", ".jpeg", ".gif"];

	for (const extension of extensions) {
		if (unresolvedNames.length === 0) {
			break;
		}

		const candidateByItemName = new Map(
			unresolvedNames.map((itemName) => [
				itemName,
				`${itemName.replace(/ /g, "_")}${extension}`,
			]),
		);

		const resolvedByFilename = new Map();
		const candidates = [...candidateByItemName.values()];
		for (
			let offset = 0;
			offset < candidates.length;
			offset += IMAGE_TITLES_PER_QUERY
		) {
			const batch = candidates.slice(offset, offset + IMAGE_TITLES_PER_QUERY);
			const batchUrls = await resolveImageUrlsBatch(batch);
			for (const [filename, url] of batchUrls) {
				resolvedByFilename.set(filename, url);
			}
		}

		unresolvedNames = unresolvedNames.filter((itemName) => {
			const filename = candidateByItemName.get(itemName);
			const imageUrl = resolvedByFilename.get(normalizeFileTitle(filename));
			if (imageUrl) {
				itemUrls.set(itemName, imageUrl);
				return false;
			}

			return true;
		});
	}

	return itemUrls;
}

/**
 * Download a batch-resolved image. Items whose generated image filenames do
 * not resolve are reported as failures; there is no interactive fallback, so
 * an unattended run continues directly to the next item.
 *
 * @param {string} itemName Item page title.
 * @param {string} cultureDirectory Destination culture directory.
 * @param {string | undefined} imageUrl Batch-resolved image URL.
 * @returns {Promise<void>}
 */
async function downloadItemImage(itemName, cultureDirectory, imageUrl) {
	if (!imageUrl) {
		throw new Error("No generated image filename resolved");
	}

	await downloadImageIfNeeded(imageUrl, cultureDirectory, itemName);
}
/**
 * Map an HTTP image Content-Type to the extension that matches the downloaded
 * bytes. Fandom may return a WebP representation even when its MediaWiki URL
 * contains an older filename such as Broken_Club.png.
 *
 * @param {string | string[] | undefined} contentType HTTP Content-Type header.
 * @returns {string} Matching extension, or an empty string when unknown.
 */
function getExtensionFromContentType(contentType) {
	const headerValue = Array.isArray(contentType) ? contentType[0] : contentType;
	if (typeof headerValue !== "string") {
		return "";
	}

	const mediaType = headerValue.split(";", 1)[0].trim().toLowerCase();
	const extensions = {
		"image/avif": ".avif",
		"image/gif": ".gif",
		"image/jpeg": ".jpg",
		"image/png": ".png",
		"image/webp": ".webp",
	};

	return extensions[mediaType] || "";
}

/**
 * Create an item image filename from the item page title and resolved URL.
 * Spaces are changed to underscores as required. When an image response has a
 * known Content-Type, its extension wins so the filename always matches the
 * downloaded binary. Otherwise, the extension is read from the resolved URL.
 *
 * @param {string} itemName Item title.
 * @param {string} imageUrl Resolved image URL.
 * @param {string | string[] | undefined} [contentType] HTTP Content-Type header.
 * @returns {string} Output filename.
 */
function getImageFilename(itemName, imageUrl, contentType) {
	let extension = getExtensionFromContentType(contentType);

	if (!extension) {
		const pathname = decodeURIComponent(new URL(imageUrl).pathname);

		// Fandom commonly appends /revision/latest to an image URL. In that
		// format the final segment is "latest", while the actual filename and
		// extension are an earlier path segment (for example Broken_Club.png).
		for (const segment of pathname.split("/").reverse()) {
			extension = path.extname(segment);
			if (extension) {
				break;
			}
		}
	}

	if (!extension) {
		throw new Error(`Resolved image URL has no file extension: ${imageUrl}`);
	}

	// Avoid path traversal from unexpected remote title data while retaining
	// normal item punctuation. Standard titles only need the space change.
	const safeName = itemName.replace(/ /g, "_").replace(/[\\/]/g, "_");
	if (!safeName || safeName === "." || safeName === "..") {
		throw new Error(`Invalid item name for image filename: ${itemName}`);
	}

	return `${safeName}${extension}`;
}

/**
 * Check whether a path exists without treating other filesystem errors as a
 * missing image. Existing images are deliberately reused and never replaced.
 *
 * @param {string} filePath Filesystem path to test.
 * @returns {Promise<boolean>} True only when the file exists.
 */
async function fileExists(filePath) {
	try {
		await fs.access(filePath);
		return true;
	} catch (error) {
		if (error && error.code === "ENOENT") {
			return false;
		}

		throw error;
	}
}

/**
 * Download an image only when its destination filename does not already exist.
 * The initial URL-based filename avoids an unnecessary request for the common
 * case. After downloading, the response Content-Type selects the final
 * extension (for example .webp), which keeps Fandom's adaptive image formats
 * from being saved under a misleading .png name.
 *
 * @param {string} imageUrl Resolved image URL.
 * @param {string} cultureDirectory Destination culture directory.
 * @param {string} itemName Item page title.
 * @returns {Promise<'downloaded' | 'existing'>} Download result.
 */
async function downloadImageIfNeeded(imageUrl, cultureDirectory, itemName) {
	const urlFilename = getImageFilename(itemName, imageUrl);
	if (await fileExists(path.join(cultureDirectory, urlFilename))) {
		return "existing";
	}

	const { body, headers } = await fetchResource(imageUrl);
	const destinationFilename = getImageFilename(
		itemName,
		imageUrl,
		headers["content-type"],
	);
	const destinationPath = path.join(cultureDirectory, destinationFilename);
	if (await fileExists(destinationPath)) {
		return "existing";
	}

	const temporaryPath = `${destinationPath}.part-${process.pid}-${Date.now()}`;

	try {
		await fs.writeFile(temporaryPath, body, { flag: "wx" });

		// link() succeeds only when the destination does not yet exist. This
		// makes the final placement atomic and guarantees another process's
		// existing image is never overwritten.
		try {
			await fs.link(temporaryPath, destinationPath);
		} catch (error) {
			if (error && error.code === "EEXIST") {
				return "existing";
			}

			throw error;
		}

		return "downloaded";
	} catch (error) {
		throw new Error(
			`Could not save image to ${destinationPath}: ${error.message}`,
		);
	} finally {
		try {
			await fs.unlink(temporaryPath);
		} catch (cleanupError) {
			if (!cleanupError || cleanupError.code !== "ENOENT") {
				// The completed image is already safe; temporary cleanup is
				// best effort and must not hide the original result/error.
			}
		}
	}
}
/**
 * Turn a page title into the exact JSON name field required by the output.
 * Only spaces become underscores; no extra metadata is emitted in prices.json.
 *
 * @param {string} itemName Original page title.
 * @returns {string} JSON item name.
 */
function getJsonItemName(itemName) {
	return itemName.replace(/ /g, "_");
}

/**
 * Process one Cargo item using the base value inferred from its PerfectN field.
 * A missing image is reported but does not discard a valid price entry.
 *
 * @param {{name: string, perfectN: string | number}} item Cargo item reference.
 * @param {string} cultureDirectory Destination culture directory.
 * @param {string | undefined} imageUrl Batch-resolved image URL.
 * @returns {Promise<{entry: {name: string, prices: {low: number, normal: number, high: number}, ng_plus_prices: {low: number, normal: number, high: number}}, imageError: Error | null}>} Item result.
 */
async function processItem(item, cultureDirectory, imageUrl) {
	const value = getBaseValueFromPerfectN(item.perfectN);
	const priceData = calculatePrices(value);
	const entry = {
		name: getJsonItemName(item.name),
		prices: priceData.prices,
		ng_plus_prices: priceData.ng_plus_prices,
	};

	try {
		await downloadItemImage(item.name, cultureDirectory, imageUrl);
		return { entry, imageError: null };
	} catch (error) {
		return {
			entry,
			imageError: error instanceof Error ? error : new Error(String(error)),
		};
	}
}
/**
 * Write the exact prices.json structure for one culture.  This overwrites only
 * prices.json each run; downloaded images remain untouched and reusable.
 *
 * @param {string} cultureDirectory Culture output folder.
 * @param {Array<{name: string, prices: object, ng_plus_prices: object}>} items Completed item entries.
 * @returns {Promise<void>}
 */
async function writePricesFile(cultureDirectory, items) {
	const outputPath = path.join(cultureDirectory, "prices.json");
	const json = `${JSON.stringify({ items }, null, 4)}\n`;
	await fs.writeFile(outputPath, json, "utf8");
}

/**
 * Import one culture while isolating failures to individual items.  Its output
 * directory is created first, and prices.json is always overwritten even if
 * Cargo itself fails, leaving a valid empty item list for that culture.
 *
 * @param {{name: string, directory: string}} culture Culture configuration.
 * @param {string} outputRoot Absolute items directory.
 * @returns {Promise<void>}
 */
async function processCulture(culture, outputRoot) {
	const cultureDirectory = path.join(outputRoot, culture.directory);
	await fs.mkdir(cultureDirectory, { recursive: true });
	console.log(`${culture.name}:`);

	const completedItems = [];

	try {
		const items = await fetchCultureItems(culture.name);
		let imageUrls = new Map();

		try {
			imageUrls = await resolveGeneratedImageUrls(items);
		} catch (error) {
			// Price data still comes from the Cargo response, so retain it even
			// if an unexpected image-batch failure prevents automatic images.
			console.error(
				`  Could not batch-resolve ${culture.name} images: ${error.message}`,
			);
		}

		for (const item of items) {
			try {
				const result = await processItem(
					item,
					cultureDirectory,
					imageUrls.get(item.name),
				);
				if (result.imageError) {
					console.error(`  ${item.name} \u2717 (${result.imageError.message})`);
				} else {
					// prices.json contains only items whose images are present.
					completedItems.push(result.entry);
					console.log(`  ${item.name} \u2713`);
				}
			} catch (error) {
				console.error(`  ${item.name} \u2717 (${error.message})`);
			}
		}
	} catch (error) {
		console.error(
			`  Could not retrieve ${culture.name} items: ${error.message}`,
		);
	} finally {
		try {
			await writePricesFile(cultureDirectory, completedItems);
		} catch (error) {
			console.error(`  Could not write prices.json: ${error.message}`);
		}
	}

	console.log("");
}

/**
 * Main entry point.  The directories are made automatically under the current
 * working directory, so running this file from the desired location produces
 * items/merchant through items/ict with no setup or configuration required.
 */
async function main() {
	// A lightweight guard confirms the formulas match the required Vine test
	// case before any network traffic or output files are created.
	const vinePrices = calculatePrices(2n);
	const expectedVine = JSON.stringify({
		prices: { low: 2, normal: 3, high: 3 },
		ng_plus_prices: { low: 9, normal: 13, high: 16 },
	});
	if (JSON.stringify(vinePrices) !== expectedVine) {
		throw new Error(
			"Internal price formula verification failed for Vine (value=2)",
		);
	}

	// Directory creation is recursive, making both first-time and repeat runs
	// safe.  Individual culture folders are also ensured by processCulture.
	const outputRoot = path.join(process.cwd(), "assets", "items");
	await fs.mkdir(outputRoot, { recursive: true });

	for (const culture of CULTURES) {
		await processCulture(culture, outputRoot);
	}
}

// Report unexpected top-level setup failures with a non-zero exit code.  Item
// and culture failures are already handled internally, so they never abort the
// rest of the import.
main().catch((error) => {
	console.error(`Fatal error: ${error.message}`);
	process.exitCode = 1;
});
